        }

        /* --- АНИМАЦИЯ REVEAL --- */
        @supports (animation-timeline: view()) {
            .reveal {
                opacity: 0;
                transform: translateY(80px) scale(0.9);
                filter: blur(10px);
                animation: revealAnim linear both;
                animation-timeline: view();
                animation-range-start: entry 20%;
                animation-range-end: entry 80%
            }

            @keyframes revealAnim {
                from {
                    opacity: 0;
                    transform: translateY(80px) scale(0.9);
                    filter: blur(10px)
                }

                to {
                    opacity: 1;
                    transform: translateY(0) scale(1);
                    filter: blur(0)
                }
            }
        }

        @supports not (animation-timeline: view()) {
            .reveal {
                opacity: 1;
                transform: none;
                filter: none
            }
        }

        .section-title {
            position: relative;
            display: inline-block;
            text-align: left
        }

        .section-title::after {
            content: \'\';
            position: absolute;
            bottom: -8px;
            left: 0;
            width: 60px;
            height: 3px;
            background: linear-gradient(90deg, #3F5F3F, #d4a574);
            border-radius: 2px
        }

        .text-center .section-title::after {
            left: 50%;
            transform: translateX(-50%)
        }

        .hero-slider {
            height: 100vh;
            min-height: 700px
        }

        .hero-slide {
            position: relative;
            height: 100%
        }

        .hero-slide img {
            width: 100%;
            height: 100%;
            object-fit: cover
        }

        .hero-overlay {
            position: absolute;
            inset: 0;
            background: linear-gradient(to right, rgba(0, 0, 0, 0.85) 0%, rgba(0, 0, 0, 0.5) 50%, transparent 100%)
        }

        @keyframes ticker {
            0% {
                transform: translateX(0)
            }

            100% {
                transform: translateX(-50%)
            }
        }

        .animate-ticker {
            animation: ticker 35s linear infinite
        }

        .timeline-line {
            position: absolute;
            left: 24px;
            top: 0;
            bottom: 0;
            width: 2px;
            background: linear-gradient(to bottom, #3F5F3F, #d4a574);
